    if (gradePrefs.present) {
      map['grade_prefs'] = Variable<String>(gradePrefs.value);
    }
    if (theme.present) {
      map['theme'] = Variable<String>(theme.value);
    }
    if (language.present) {
      map['language'] = Variable<String>(language.value);
    }
    if (quietHours.present) {
      map['quiet_hours'] = Variable<String>(quietHours.value);
    }
    if (rowid.present) {
      map['rowid'] = Variable<int>(rowid.value);
    }
    return map;
  }

  @override
  String toString() {
    return (StringBuffer('ProfilesCompanion(')
          ..write('id: $id, ')
          ..write('createdAt: $createdAt, ')
          ..write('updatedAt: $updatedAt, ')
          ..write('deletedAt: $deletedAt, ')
          ..write('displayName: $displayName, ')
          ..write('avatarMediaId: $avatarMediaId, ')
          ..write('homeAreaId: $homeAreaId, ')
          ..write('defaultVisibility: $defaultVisibility, ')
          ..write('rackVisibility: $rackVisibility, ')
          ..write('gradePrefs: $gradePrefs, ')
          ..write('theme: $theme, ')
          ..write('language: $language, ')
          ..write('quietHours: $quietHours, ')
          ..write('rowid: $rowid')
          ..write(')'))
        .toString();
  }
}

