class Session extends DataClass implements Insertable<Session> {
  /// UUIDv7, generated on the device.
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;

  /// Set instead of deleting; clients never hard-delete rows.
  final DateTime? deletedAt;
  final String ownerId;
  final String visibility;
  final String? tripId;
  final String? climbGroupId;
  final String? areaId;

  /// `outdoor` or `indoor`.
  final String setting;

  /// `YYYY-MM-DD` in the session's own time zone.
  final String localDate;

  /// IANA time zone, for example `Europe/Oslo`.
  final String tz;
  final DateTime? startAt;
  final DateTime? endAt;
  final String? title;
  final String? description;
  final bool locationHidden;
  final String? defaultShoeId;
  final int? elevationGainM;
  final String? conditions;
  const Session({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
    required this.ownerId,
    required this.visibility,
    this.tripId,
    this.climbGroupId,
    this.areaId,
    required this.setting,
    required this.localDate,
    required this.tz,
    this.startAt,
    this.endAt,
    this.title,
    this.description,
    required this.locationHidden,
    this.defaultShoeId,
    this.elevationGainM,
    this.conditions,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    map['owner_id'] = Variable<String>(ownerId);
    map['visibility'] = Variable<String>(visibility);
    if (!nullToAbsent || tripId != null) {
      map['trip_id'] = Variable<String>(tripId);
    }
    if (!nullToAbsent || climbGroupId != null) {
      map['climb_group_id'] = Variable<String>(climbGroupId);
    }
    if (!nullToAbsent || areaId != null) {
      map['area_id'] = Variable<String>(areaId);
    }
    map['setting'] = Variable<String>(setting);
    map['local_date'] = Variable<String>(localDate);
    map['tz'] = Variable<String>(tz);
    if (!nullToAbsent || startAt != null) {
      map['start_at'] = Variable<DateTime>(startAt);
    }
    if (!nullToAbsent || endAt != null) {
      map['end_at'] = Variable<DateTime>(endAt);
    }
    if (!nullToAbsent || title != null) {
      map['title'] = Variable<String>(title);
    }
    if (!nullToAbsent || description != null) {
      map['description'] = Variable<String>(description);
    }
    map['location_hidden'] = Variable<bool>(locationHidden);
    if (!nullToAbsent || defaultShoeId != null) {
      map['default_shoe_id'] = Variable<String>(defaultShoeId);
    }
    if (!nullToAbsent || elevationGainM != null) {
      map['elevation_gain_m'] = Variable<int>(elevationGainM);
    }
    if (!nullToAbsent || conditions != null) {
      map['conditions'] = Variable<String>(conditions);
    }
    return map;
  }

  SessionsCompanion toCompanion(bool nullToAbsent) {
    return SessionsCompanion(
      id: Value(id),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      deletedAt: deletedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAt),
      ownerId: Value(ownerId),
      visibility: Value(visibility),
      tripId: tripId == null && nullToAbsent
